SELECT CASE WHEN discount >= 0.35 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, channel, DATE_TRUNC('WEEK', order_date) AS week_start, COUNT_IF(status = 'RETURNED') AS returned_events, ROUND(AVG(discount), 2) AS avg_discount, SIZE(COLLECT_SET(channel)) AS num_channels, CORR(amount, discount) AS corr_amount_discount, PERCENT_RANK() OVER (PARTITION BY CASE WHEN discount >= 0.35 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(discount), 2) DESC) AS avg_discount_percent_rank FROM orders GROUP BY CASE WHEN discount >= 0.35 THEN 'HIGH' ELSE 'LOW' END, channel, DATE_TRUNC('WEEK', order_date) ORDER BY returned_events DESC NULLS FIRST;
